<?php
$title='Dashboard';
$k=DB::row("SELECT COUNT(*) t,SUM(map_score IS NOT NULL) au,SUM(stage IN ('report_ready','contacting','contacted','opened','replied','won','lost')) rr,SUM(email_status IN ('sent','opened') OR wa_status IN ('sent','delivered','read','manual')) ct,SUM(email_status='opened' OR wa_status='read' OR stage='opened') op,SUM(replied_at IS NOT NULL) rp,SUM(stage='won') wn,SUM(website='') nw FROM leads");
$k=array_map('intval',$k);
$camps=DB::all('SELECT c.*,(SELECT COUNT(*) FROM leads WHERE campaign_id=c.id AND (email_status IN (\'sent\',\'opened\') OR wa_status IN (\'sent\',\'delivered\',\'read\',\'manual\'))) ct FROM campaigns c ORDER BY id DESC LIMIT 6');
$ev=DB::all('SELECT e.*,l.name FROM events e JOIN leads l ON l.id=e.lead_id ORDER BY e.id DESC LIMIT 14');
$ai=setting('ai_key_'.setting('ai_provider','anthropic'))!=='';
$maps=setting('maps_source')==='serpapi'?setting('serpapi_key')!=='':setting('google_api_key')!=='';
$checks=[[$ai,'Connect an AI provider','ai'],[$maps,'Add Google Maps data source key','settings&tab=data'],[Mailer::ready(),'Configure SMTP email','settings&tab=email'],[setting('wa_provider')!=='manual','Connect WhatsApp API (optional – manual mode works)','settings&tab=whatsapp'],[setting('company_logo')!=='','Company info & branding','settings'],[(int)setting('cron_last','0')>time()-86400,'Set up the cron job (see Updates → Go live)','updates']];
$done=count(array_filter(array_column($checks,0)));
$rate=$k['ct']?round($k['rp']/$k['ct']*100,1):0;
$fun=[['Found',$k['t']],['Audited',$k['au']],['Report ready',$k['rr']],['Contacted',$k['ct']],['Opened / viewed',$k['op']],['Replied',$k['rp']],['Won',$k['wn']]];$max=max(1,$k['t']);
?>
<div class="kpis"><div class="kpi"><span>Total leads</span><b><?=$k['t']?></b><small><?=$k['nw']?> without website</small></div><div class="kpi"><span>Reports generated</span><b><?=$k['rr']?></b><small><?=$k['au']?> audited</small></div><div class="kpi"><span>Contacted</span><b><?=$k['ct']?></b><small>Email + WhatsApp</small></div><div class="kpi kpi-g"><span>Replies</span><b><?=$k['rp']?></b><small><?=$rate?>% reply rate</small></div></div>
<?php if($done<count($checks)):?><div class="card"><div class="card-h"><h3>Getting started</h3><span class="muted"><?=$done?>/<?=count($checks)?> done</span></div><div class="prog"><i style="width:<?=round($done/count($checks)*100)?>%"></i></div><div class="steps"><?php foreach($checks as [$ok,$l,$u]):?><a href="index.php?r=<?=$u?>" class="step <?=$ok?'ok':''?>"><?=icon($ok?'check':'clock')?><span><?=e($l)?></span></a><?php endforeach?></div></div><?php endif?>
<div class="g2"><div class="card"><div class="card-h"><h3>Outreach funnel</h3></div><div class="fun"><?php foreach($fun as [$l,$n]):?><div class="fr"><span><?=e($l)?></span><div><i style="width:<?=max(2,round($n/$max*100))?>%"></i></div><b><?=$n?></b></div><?php endforeach?></div></div>
<div class="card"><div class="card-h"><h3>Recent activity</h3><a href="<?=url('leads')?>" class="lnk">All leads</a></div><?php if(!$ev):?><div class="empty sm"><?=icon('activity')?><p>No activity yet. Start with a new search.</p></div><?php else:?><ul class="feed"><?php foreach($ev as $x):?><li class="ev-<?=e($x['type'])?>"><i></i><div><a href="<?=url('lead',['id'=>$x['lead_id']])?>"><b><?=e($x['name'])?></b></a> <span><?=e($x['message'])?></span><small><?=ago($x['created_at'])?></small></div></li><?php endforeach?></ul><?php endif?></div></div>
<div class="card"><div class="card-h"><h3>Recent searches</h3><a href="<?=url('campaigns')?>" class="lnk">View all</a></div><?php if(!$camps):?><div class="empty"><?=icon('search')?><h4>No searches yet</h4><p>Enter a keyword like “dentist in Pune” to find businesses on Google Maps.</p><a class="btn btn-g" href="<?=url('campaigns',['new'=>1])?>"><?=icon('plus')?>New Search</a></div><?php else:?><div class="tw"><table class="tbl"><thead><tr><th>Keyword</th><th>Location</th><th>Found</th><th>Contacted</th><th>Status</th><th>Created</th></tr></thead><tbody><?php foreach($camps as $c):?><tr onclick="location='<?=url('campaign',['id'=>$c['id']])?>'" class="clk"><td><b><?=e($c['keyword'])?></b></td><td><?=e($c['location'])?></td><td><?=$c['found']?>/<?=$c['limit_n']?></td><td><?=$c['ct']?></td><td><?=cbadge($c['status'])?></td><td class="muted"><?=ago($c['created_at'])?></td></tr><?php endforeach?></tbody></table></div><?php endif?></div>
